mapper.select:
SELECT p.* FROM product_spu p WHERE p.deleted = FALSE
AND (p.spu_code ILIKE CONCAT('%',#{query.keyword},'%') OR p.name ILIKE CONCAT('%',#{query.keyword},'%') OR p.alias ILIKE CONCAT('%',#{query.keyword},'%') OR EXISTS (SELECT 1 FROM product_sku s WHERE s.spu_id=p.id AND s.deleted=FALSE AND (s.sku_code ILIKE CONCAT('%',#{query.keyword},'%') OR s.barcode ILIKE CONCAT('%',#{query.keyword},'%'))))
AND p.category_id IN #{id}
AND p.status=#{query.status}
AND EXISTS (SELECT 1 FROM product_sku s WHERE s.spu_id=p.id AND s.deleted=FALSE AND s.status=#{query.skuStatus} AND s.product_type=#{query.productType})
